function is_strong_password(password: str) -> bool:
    # Check if the password length is at least 8 characters
    if len(password) < 8:
        return False

    # Check for at least one uppercase letter (A-Z)
    if not any(c.isupper() for c in password):
        return False

    # Check for at least one digit (0-9)
    if not any(c.isdigit() for c in password):
        return False

    # Check for at least one special character symbol
    if not any(c.isspecial() for c in password):
        return False

    # All checks passed
    return True

This function will return `True` only if the password meets all specified criteria.

def average(numbers):
    if not numbers:
        return 0
    total = 0
    for n in numbers:
        total += n
    return total / len(numbers)

print(average([]))
